const CITIES = { Lagos: [6.52, 3.38], Abuja: [9.06, 7.49], Kano: [12.0, 8.52] }
const CODES = { 0: "Clear sky", 1: "Mainly clear", 2: "Partly cloudy", 3: "Overcast", 61: "Rain", 63: "Rain", 95: "Thunderstorm" }
const describe = (code) => CODES[code] ?? "Unknown"
const go = document.querySelector("#go")
const status = document.querySelector("#status")
const current = document.querySelector("#current")

async function showWeather(city, fetchFn = fetch) {
  status.textContent = "Loading…"
  go.disabled = true
  try {
    const [lat, lon] = CITIES[city]
    const params = new URLSearchParams({ latitude: lat, longitude: lon, current: "temperature_2m,weather_code" })
    const response = await fetchFn(`https://api.open-meteo.com/v1/forecast?${params}`)
    if (!response.ok) throw new Error(`HTTP ${response.status}`)
    const data = await response.json()
    current.textContent = `${city}: ${describe(data.current.weather_code)}, ${data.current.temperature_2m}°C`
    status.textContent = ""
  } catch {
    current.textContent = ""
    status.textContent = "Couldn't get the weather"
  } finally {
    go.disabled = false
  }
}
go.addEventListener("click", () => showWeather(document.querySelector("#city").value))
